const cluster = require('cluster');
const os = require('os');

// 1. The Master Process runs first
if (cluster.isMaster) {
  const numCPUs = os.cpus().length;
  console.log(`Master process ${process.pid} is running.`);
  console.log(`Forking ${numCPUs} workers...\n`);

  // Create a worker for every CPU core
  for (let i = 0; i < numCPUs; i++) {
    cluster.fork();
  }

  // If a worker crashes, immediately spawn a replacement!
  cluster.on('exit', (worker, code, signal) => {
    console.log(`Worker ${worker.process.pid} died. Respawning...`);
    cluster.fork();
  });

} else {
  // 2. The Worker Processes run this code
  // This code executes 8 times (if you have an 8-core CPU)
  const express = require('express');
  const app = express();

  app.get('/', (req, res) => {
    res.send(`Hello from Worker ${process.pid}`);
  });

  // All workers share port 3000 perfectly!
  // app.listen(3000, () => console.log(`Worker ${process.pid} listening`));
}

console.log("In production, developers almost never write this manually. They use PM2 (pm2 start app.js -i max) to do it automatically.");
